import { convertDegreeToRadians } from '../../utils/helpers';
import CylinderStack from './CylinderStack';
import { getScaleXBounded, getScaleY } from "../../utils/dimensions";


const CAKE_INNER_COLOR = "#8B5A3C";
const CAKE_OUTER_COLOR = "#5D4037";
const DRIP_COLOR = "#8B5A3C";

export default class Cake extends CylinderStack { 

  constructor(
    x, y, startAngle=0, endAngle=convertDegreeToRadians(360),
  ) {
    super(
      x, y, 200, 200, startAngle, endAngle, CAKE_INNER_COLOR, CAKE_OUTER_COLOR
    );
  }

  draw() {
    super.draw();
    
    const { ctx, x, y, r, startAngle, endAngle } = this;
    
    ctx.save();
    ctx.translate(x, y);
    ctx.save();
    ctx.scale(getScaleXBounded(), 0.5 * getScaleY());
    
    ctx.strokeStyle = DRIP_COLOR;
    ctx.lineCap = 'round';
    
    const numDrips = 20;
    const visibleStart = startAngle + (endAngle - startAngle) * 0.05;
    const visibleEnd = endAngle - (endAngle - startAngle) * 0.01;
    const angleStep = (visibleEnd - visibleStart) / numDrips;
    
    for (let i = 0; i < numDrips; i++) {
      const angle = visibleStart + angleStep * i;
      const xPos = r * Math.cos(angle);
      const yPos = r * Math.sin(angle);
      
      const isLong = i % 2 === 0;
      const dripLength = isLong ? 125 : 75;
      
      const normalizedPos = i / (numDrips - 1);
      const distanceFromCenter = Math.abs(normalizedPos - 0.5) * 2;
      const bulbSize = 4 - (distanceFromCenter * 1.5);
      
      ctx.fillStyle = DRIP_COLOR;
      ctx.beginPath();
      ctx.arc(xPos, yPos, bulbSize, 0, Math.PI * 2);
      ctx.fill();
      
      ctx.beginPath();
      ctx.moveTo(xPos, yPos);
      ctx.lineTo(xPos, yPos + dripLength);
      ctx.lineWidth = 3;
      ctx.stroke();
      
      ctx.beginPath();
      ctx.arc(xPos, yPos + dripLength, 2.5, 0, Math.PI * 2);
      ctx.fill();
    }
    
    ctx.restore();
    ctx.restore();
  }
}